D.LocalClientValues[40145]="魔兽世界旨在提供有趣、公平并且安全的游戏环境。如果您遇到玩家使用|cffffd200包含人身攻击性的名字|r，或者在聊天时发送|cffffd200骚扰|r信息，在游戏中|cffffd200作弊|r，或是使用|cffffd200不当语言|r，您都可以快捷方便地向暴雪举报。\\n\\n要举报玩家破坏游戏规则或者带有人身攻击性的行为，请|cffffd200右键点击玩家的名字|r，并且点选|cffffd200举报玩家|r。"
