D.LocalClientValues[40866]="暗矛部落的巨魔原本居住在荆棘谷的丛林中，但是由于各阵营之间的连年征战而被迫流离失所。兽人的部落向他们伸出了援手，并说服暗矛部落渡过无尽之海，在卡利姆多的蛮荒之地定居下来。虽然他们继承了巨魔种族的黑暗本性，但是暗矛巨魔主张保持部落的团结，并愿意以强大的武力和原始部族魔法为部落共同的事业而效力。"
