D.LocalClientValues[43485]="人类是个年轻而多才多艺的种族，可以以惊人的效率学习战斗技巧、制造技术和操控魔法的技艺。靠着勇猛和乐观的天性，人类建造了许多世界上最伟大的王国。在这个动乱的时代，经历了世代纷争的人类正在努力恢复昔日的辉煌，创造光明的未来。"
