D.LocalClientValues[43519]="练习赛"
D.LocalClientValues[43520]="在第三次战争期间，东部王国的大法师阿鲁高将狼人释放到了这个世界上。狼人最初被当作对抗亡灵天灾的武器，然而不久之后，这些野兽就变成了洛丹伦的人民难以承受的灾厄。某种神秘的诅咒开始传播，将那些与狼人一同作战的人类也变成了这种獠牙利爪的怪物。诅咒很快就蔓延到了吉尔尼斯王国，王国的居民被困在了那堵原本建来保护他们的高墙之后。现在，诅咒的幸存者正为他们的人民寻求新的命运，历史的宿命又翻开了一页……"
