D.LocalClientValues[45286]="很久以前，高贵的高等精灵围绕着名为太阳之井的魔法喷泉建立起了黄金之城奎尔萨拉斯。但在第三次大战中，巫妖王摧毁了他们的都城，幸存者们只得向部落求助。\\n\\n这些如今自称为血精灵的流亡者已经是这个灿烂文明的最后遗孑。他们一直致力于重建奎尔萨拉斯，并努力与曾经建立起他们帝国的那股魔法能量的诱惑做斗争。"
